"""Build the public 50-minute project session from selected supplied module ideas.
Private facilitation text is sealed separately, never loaded by this module.
"""
import json
from pathlib import Path
from html import escape as e

def build_pm(api):
 R=api['R'];page,heading,section,link,ul,challenge,countdown=[api[k] for k in ['page','heading','section','link','ul','challenge','countdown']]
 s=next(s for s in json.loads((R/'data/sessions.json').read_text()) if s['id']=='project-management');d=json.loads((R/'data/project-management.json').read_text());SP='sessions/project-management/';DD='downloads/project-management/';out=R/DD;out.mkdir(parents=True,exist_ok=True)
 def nav():return '<nav class="session-nav" aria-label="Project management session"><div class="container">'+''.join('<a href="@@'+SP+p+'">'+t+'</a>' for p,t in [('index.html','Overview'),('participate.html','Participate'),('toolkit.html','Toolkit and downloads'),('presenter-guide.html','Presenter guide')])+'</div></nav>'
 def show(path,title,body):page(SP+path,title,nav()+body,'sessions')
 def img(name,alt):return '<figure class="pm-visual"><img class="pm-diagram" src="@@assets/infographics/'+name+'.svg" width="1200" height="370" alt="'+e(alt)+'"><figcaption>'+e(alt)+'</figcaption></figure>'
 agenda='<ol class="agenda">'+''.join('<li><time>'+str(a['start'])+'–'+str(a['end'])+' min</time><div><strong>'+e(a['title'])+'</strong><p>Think, discuss, check, and revise.</p></div></li>' for a in d['agenda'])+'</ol>'
 body=heading('Project Management',s['title'],'A focused 50-minute session with practical models, individual thinking, and short neighbor discussions.')+section('<div class="split"><div class="prose"><h2>Make the next decision clearer.</h2><p>'+e(s['fullDescription'])+'</p><div class="actions">'+link('@@'+SP+'participate.html','Start the case experience')+link('@@'+SP+'presenter-guide.html','Open presenter guide','button ghost')+'</div><h2>Learning objectives</h2>'+ul(s['learningObjectives'])+'<h2>Success criteria</h2>'+ul(s['successCriteria'])+'</div><aside class="card"><p class="eyebrow">Your 50-minute route</p><h2>Content and conversation</h2>'+agenda+'</aside></div>')+section(img('project-route','Define the work, coordinate people, and verify delivery and adoption.')+'<div class="callout"><strong>One fictional case, several useful decisions.</strong><p>'+e(d['case']['facts'])+'</p></div><p class="small muted">'+e(d['sourceNote'])+'</p>','pale')
 show('index.html',s['title'],body)
 sections=[]
 for a in d['agenda']:
  id=a['id'];content=''
  if id=='pm-notice':content=challenge('pm-next-action','What is the strongest next action?',['Promise a date without checking the dependency','Bring decision owners together, name the blocker, and agree an interim plan','Buy another tool before clarifying the need'],'Bring the relevant owners together, identify what each team needs, name who can resolve the dependency, and agree an interim instructional plan and a dependable next update. The case does not provide evidence for a completion date.')
  elif id=='pm-charter':content=img('pm-lifecycle','Define the need, plan owners and risks, coordinate the work, and review usefulness.')+'<div class="grid two"><div class="card"><h3>Model a boundary</h3><p><strong>In scope:</strong> restore and verify usable service in the portable classroom.</p><p><strong>Out of scope:</strong> redesign every campus network.</p></div><div class="card"><h3>Think and compare</h3><p>Write a one-sentence problem, an outcome someone could accept, and one exclusion. Ask a neighbor which phrase needs clarification.</p></div></div>'
  elif id=='pm-dependencies':content=img('project-update','Make status, blocker, owner, and decision visible.')+'<div class="callout"><h3>Complete the handoff</h3><p>Before ______ can happen, ______ must be ready.</p><p>______ owns the handoff and will provide ______.</p><p>If ______ happens, we will escalate to ______.</p></div><p>Draft quietly, compare with a neighbor, then revise one unclear owner or dependency. Distinguish an existing issue from a possible future risk.</p>'
  elif id=='pm-adoption':content=challenge('pm-success-evidence','Which statement points to stronger acceptance evidence?',['The installation task is marked complete','The service passes agreed tests and the teacher can use it in the intended lesson'],'The second statement adds agreed tests and actual use. Verify the evidence and the acceptance owner. Delivery can be necessary without proving adoption or usefulness. Choose one delivery indicator and one use/adoption indicator; set baselines and targets from local evidence.')+img('pm-success-scorecard','Consider technical reliability, operating capacity, instructional usefulness, and adoption.')+'<p><strong>Neighbor prompt:</strong> What does the principal need in the next update? Include status, blocker, owner, next decision, and the next check.</p><details class="answer"><summary>Consider individual change</summary><p>Prosci’s ADKAR model names Awareness, Desire, Knowledge, Ability, and Reinforcement. Use questions about understanding, concerns, know-how, actual performance, and continuing support. A technical or structural barrier may need a different response from training.</p><a href="https://www.prosci.com/methodology/adkar" target="_blank" rel="noopener noreferrer">Primary ADKAR reference ↗</a></details>'
  elif id=='pm-plan':
   fields=''.join('<label for="pm-field-'+str(i)+'">'+e(label)+'</label><textarea id="pm-field-'+str(i)+'" data-label="'+e(label)+'" maxlength="3000"></textarea>' for i,label in enumerate(d['planningFields']))
   content='<p>Spend four quiet minutes drafting. Compare with a neighbor for four minutes, then use the final two minutes to revise one gap. Use fictional or generalized details. No plans are submitted.</p><form class="reflection" id="pm-plan-form">'+fields+'<div class="actions"><button type="button" id="pm-copy">Copy plan</button><button type="button" class="button ghost" id="pm-print">Print plan</button><button type="reset" class="button ghost">Clear plan</button></div><p id="pm-plan-status" role="status"></p></form><p class="small muted">Your plan stays in page memory. Copy or print before leaving; reloading clears it.</p>'
  elif id=='pm-commit':content='<div class="callout"><h3>Name the next conversation</h3><p>Who should be involved? What decision will you request? What evidence will you bring? When will you review the result?</p></div><p>Return to the success criteria and choose one manageable next step. Keep your own copy of the plan.</p>'+link('@@'+SP+'toolkit.html','Get the planning toolkit')
  sections.append('<section class="activity" id="'+id+'"><p class="eyebrow">'+str(a['start'])+'–'+str(a['end'])+' minutes</p><h2>'+e(a['title'])+'</h2><p class="prompt">'+e(a['prompt'])+'</p>'+content+'</section>')
 show('participate.html','Project case and planning experience',heading('Participate','Think through a project. Talk through a decision.','Work individually, compare with a neighbor, examine a model, and revise. Stay seated; use paper or the optional browser controls.')+section(countdown()+''.join(sections)))
 blocks={
 'session-handout':('Project session quick reference',[('A focused conference adaptation',d['sourceNote']),('The case',d['case']['facts']),('50-minute route','\n'.join(f'{a["start"]}-{a["end"]} min: {a["title"]}' for a in d['agenda'])),('Success criteria','\n'.join(s['successCriteria'])),('Next step','Name a person, decision, evidence, and review date.\nhttps://mglearn.github.io/tcea27/sessions/project-management/')]),
 'project-charter':('One-page project charter',[('Problem and intended outcome','What need does the project address? What result could be accepted?\n________________________________________________________'),('Scope and exclusions','What is included? What is explicitly outside this project?\n________________________________________________________'),('Authority and ownership','Who sponsors, approves, does, and accepts the work?\n________________________________________________________'),('Milestone and dependency','What must be ready before the next milestone? Who owns it?\n________________________________________________________'),('Risk and decision','What early signal requires attention? Who can decide?\n________________________________________________________'),('Evidence of success','Name delivery evidence and evidence of use/adoption.\n________________________________________________________')]),
 'stakeholder-risk-map':('Stakeholder, dependency, and risk map',[('People and decisions','Stakeholder/group | Impact or concern | Decision/approval role | Engagement owner\n________________________________________________________\n________________________________________________________'),('A useful handoff','Before ____ can happen, ____ must be ready.\n____ owns the handoff and will provide ____.\n________________________________________________________'),('Risk or existing issue','Event | Cause | Early signal | Response | Owner | Review date\n________________________________________________________\n________________________________________________________'),('Escalation','If ____ happens, ____ will request a decision from ____.\n________________________________________________________')]),
 'communication-scorecard':('Communication and success scorecard',[('A usable update','Audience | Question they need answered | Channel | Cadence | Author | Escalation trigger\n________________________________________________________\n________________________________________________________'),('Delivery evidence','Indicator | Baseline | Locally agreed target | Source | Owner | Review date\n________________________________________________________'),('Use or adoption evidence','Indicator | Baseline | Locally agreed target | Source | Owner | Review date\n________________________________________________________'),('Acceptance and sustainability','Who verifies usefulness? Who owns ongoing support? When will the result be reviewed?\n________________________________________________________'),('Evidence rule','Do not invent baselines or targets. Choose appropriate measures after reviewing local evidence.')])}
 docs=[]
 from reportlab.platypus import SimpleDocTemplate,Spacer
 from reportlab.pdfgen import canvas
 from functools import partial
 for key,(title,parts) in blocks.items():
  story=[api['para']('TCEA 2027 | MIGUEL GUHLIN','Small27'),api['para'](title,'Title27')];html=''
  for sub,text in parts:
   story.append(api['para'](sub,'Section27'));html+='<h2>'+e(sub)+'</h2>'
   for line in text.split('\n'):story.append(api['para'](line));html+='<p>'+e(line)+'</p>'
  if key=='session-handout':
   from reportlab.graphics.barcode.qr import QrCodeWidget
   from reportlab.graphics.shapes import Drawing
   from reportlab.graphics import renderSVG
   qr=QrCodeWidget('https://mglearn.github.io/tcea27/'+SP,barLevel='M');bounds=qr.getBounds();size=bounds[2]-bounds[0];drawing=Drawing(100,100,transform=[100/size,0,0,100/size,0,0]);drawing.add(qr);story.append(drawing);renderSVG.drawToFile(drawing,str(R/'assets/images/project-management-qr.svg'));html+='<img src="../../assets/images/project-management-qr.svg" width="150" height="150" alt="QR code linking to the Project Management session">'
  story.append(api['para']('Adapted from the user-supplied TCEA Module 8 Project Management and Change Leadership assets. Fictional case; no real district data. Conference adaptation by Miguel Guhlin / MG Learn.','Small27'))
  doc=SimpleDocTemplate(str(out/(key+'.pdf')),pagesize=(612,792),rightMargin=45,leftMargin=45,topMargin=42,bottomMargin=50,title=title,author='Miguel Guhlin / MG Learn',invariant=1);doc.build(story,onFirstPage=api['footer'],onLaterPages=api['footer'],canvasmaker=partial(canvas.Canvas,invariant=1))
  page(DD+key+'.html',title,heading('Project management resource',title,'Read, adapt, or print this planning resource.')+section('<div class="prose">'+html+'<div class="actions">'+link(key+'.pdf','Download PDF')+'</div></div>'),'downloads');docs.append('<article class="download"><div><h3>'+e(title)+'</h3><p>Reusable conference planning resource.</p></div><div class="actions">'+link('@@'+DD+key+'.pdf','Download PDF','button small')+link('@@'+DD+key+'.html','Read HTML','button ghost small')+'</div></article>')
  docs[-1]=docs[-1].replace('class="button small"','class="button small"')
 toolkit=heading('Project toolkit','Small artifacts. Clearer decisions.','Use the fictional case, adapt a template, and keep only the planning details that support real decisions.')+section(img('pm-toolkit','A charter, people map, update, and scorecard support project decisions.')+'<div class="download-list">'+''.join(docs)+'</div><h2 style="margin-top:40px">Frameworks and sources</h2><p>The core planning ideas are adapted from the supplied TCEA Module 8 project-management package. Its archived slides and proposed video filenames are source material, not published videos for this session.</p><p><a href="https://www.prosci.com/methodology/adkar" target="_blank" rel="noopener noreferrer">Prosci ADKAR primary reference ↗</a> · <a href="https://www.kotterinc.com/methodology/8-steps/" target="_blank" rel="noopener noreferrer">Kotter further reading ↗</a></p><p class="small muted">External references checked October 27, 2026. No numerical effectiveness claims or project-certification credit are assigned by this conference activity.</p>')
 show('toolkit.html','Project management toolkit',toolkit)
 downloads=R/'downloads.html'
 content=downloads.read_text();addition=section('<h2>Project Management resources</h2><p>Get the charter, stakeholder/risk map, communication scorecard, and session reference.</p><div class="actions">'+link('sessions/project-management/toolkit.html','Open the Project Management toolkit')+'</div>')
 content=content.replace('<section class="print-reflection',addition+'<section class="print-reflection',1);downloads.write_text(content)
 print('Built Project Management pages and four text PDFs/HTML alternatives.')
